import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
} from 'react-native';
import { useNavigation, CommonActions } from '@react-navigation/native';
import { useAppState } from '@store/AppContext';
import Avatar from '@components/name-avatar-component/name-avatar-component';
import DrawerItem from '@components/drawer-row-item/drawer-row-item';
import LogoutModal from '@components/logout-modal/logout-modal';
import { ThemeContext } from '@style/theme/theme-context.tsx';
import type { Theme } from '@types/Theme.ts';
import {
  SVGTabConciergeIcon,
  SVGDrawerApptsIcon,
  SVGTabProfileIcon,
  SVGChevronRightComponent,
  SVGDrawerMedicalRecordsIcon,
  SVGDrawerMedicationsIcon,
  SVGDrawerHealsPassIcon,
  SVGDrawerActivateIcon,
  SVGDrawerDependantsIcon,
  SVGDrawerTransactionsIcon,
  SVGDrawerHealsPlansIcon,
  SVGDrawerSignOutIcon,
} from '../../assets/svg/index';
import styles from './custom-drawer-content.styles';
import { useCurrentRoute } from '@hooks/useCurrentRoute';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

interface CustomDrawerContentProps {
  closeDrawer: () => void;
}

type RouteValue = typeof $routeNames[keyof typeof $routeNames];
const CustomDrawerContent: React.FC<CustomDrawerContentProps> = ({ closeDrawer }) => {
  const navigation = useNavigation();
  const { user } = useAppState();
  const currentRouteName = useCurrentRoute() as RouteValue;
  const insets = useSafeAreaInsets();
  const [openLogoutModal, setOpenLogoutModal] = useState<boolean>(false);

  const handleLogout = (): void => {
    setOpenLogoutModal(true);
  };

  const navigateToScreen = (screenName: RouteValue): void => {
    navigation.dispatch(
      CommonActions.navigate({
        name: screenName,
      })
    );
    closeDrawer();
  };
  const isActive = (routeNames: RouteValue | RouteValue[]): boolean => {
    if (Array.isArray(routeNames)) {
      return routeNames.includes(currentRouteName);
    }
    return currentRouteName === routeNames;
  };

  return (
    <ThemeContext.Consumer>
      {(theme: Theme) => {
        return (
          <>
            <View style={[styles.container, { paddingTop: insets.top }]}>
              <ScrollView showsVerticalScrollIndicator={false}>
                <View style={styles.header}>
                  <View style={styles.userInfo}>
                    {user?.name && <Avatar username={user?.name} style={styles.avatar} />}
                    <View style={styles.userText}>
                      <Text style={styles.userName}>{user?.name}</Text>
                      {/* todo 用户邮件字段改数据结构后再获取 */}
                      {/* {user?.email && (
                        <Text style={styles.userEmail}>{user?.email}</Text>
                      )} */}
                    </View>
                  </View>
                  <TouchableOpacity onPress={closeDrawer} style={styles.closeButton}>
                    <Text style={styles.closeText}>✕</Text>
                  </TouchableOpacity>
                </View>

                <View style={styles.divider} />

                <DrawerItem
                  LeftIcon={<SVGTabConciergeIcon focused color="#137963" width={20} height={20} />}
                  text={$i18n.t('my_concierge')}
                  RightIcon={<SVGChevronRightComponent width={20} height={20} />}
                  onPress={() => navigateToScreen($routeNames.concierge)}
                  isActive={isActive([$routeNames.concierge])}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerApptsIcon focused color="#137963" width={20} height={20} />}
                  text={$i18n.t('appointments')}
                  RightIcon={<SVGChevronRightComponent width={20} height={20} />}
                  onPress={() => navigateToScreen($routeNames.appointments)}
                  isActive={isActive([$routeNames.appointments])}
                />

                <DrawerItem
                  LeftIcon={<SVGTabProfileIcon focused color="#137963" width={20} height={20} />}
                  text={$i18n.t('profile_and_health')}
                  RightIcon={<SVGChevronRightComponent width={20} height={20} />}
                  onPress={() => navigateToScreen($routeNames.profile)}
                  isActive={isActive([$routeNames.profile])}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerMedicalRecordsIcon width={20} height={20} />}
                  text={$i18n.t('medical_records')}
                  RightIcon={<SVGChevronRightComponent fill="#D1D5DC" width={20} height={20} />}
                  onPress={() => {/* 导航逻辑 */ }}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerMedicationsIcon width={20} height={20} />}
                  text={$i18n.t('medications')}
                  RightIcon={<SVGChevronRightComponent fill="#D1D5DC" width={20} height={20} />}
                  onPress={() => {/* 导航逻辑 */ }}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerHealsPassIcon width={20} height={20} />}
                  text={$i18n.t('heals_pass')}
                  RightIcon={<SVGChevronRightComponent fill="#D1D5DC" width={20} height={20} />}
                  onPress={() => {/* 导航逻辑 */ }}
                />

                <View style={styles.divider} />

                <DrawerItem
                  LeftIcon={<SVGDrawerActivateIcon width={20} height={20} />}
                  text={$i18n.t('activate')}
                  onPress={() => {/* 激活逻辑 */ }}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerDependantsIcon width={20} height={20} />}
                  text={$i18n.t('dsi.my_dependants')}
                  onPress={() => {/* 导航逻辑 */ }}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerTransactionsIcon width={20} height={20} />}
                  text={$i18n.t('transaction_history')}
                  onPress={() => navigateToScreen($routeNames.transactionHistory)}
                />

                <DrawerItem
                  LeftIcon={<SVGDrawerHealsPlansIcon width={20} height={20} />}
                  text={$i18n.t('setting.wallet')}
                  onPress={() => {/* 导航逻辑 */ }}
                />

                <View style={styles.dividerWithoutLine} />

                <DrawerItem
                  LeftIcon={<SVGDrawerSignOutIcon width={20} height={20} />}
                  text={$i18n.t('sign_out')}
                  textStyle={styles.signOutText}
                  onPress={handleLogout}
                />
              </ScrollView>
            </View>
            <LogoutModal
              open={openLogoutModal}
              handleCancle={() => setOpenLogoutModal(false)}
            />
          </>
        );
      }}
    </ThemeContext.Consumer>
  );
};

export default CustomDrawerContent;

import React, {useEffect, useState} from 'react';
import {Modal, View, TouchableOpacity} from 'react-native';
import {LogoutModalProps} from './logout-modal.props';
import styles from './logout-modal.styles';
import AppText from '@components/app-text/app-text';
import {useAuth} from "@hooks/auth-hook-context.tsx";
import {ThemeContext} from '@style/theme/theme-context.tsx';
import type {Theme} from '@types/Theme.ts';

const LogoutModal: React.FC<LogoutModalProps> = (props: LogoutModalProps) => {
  const [logoutModal, setLogoutModal] = useState<boolean>(false);
  const { logout } = useAuth();

  useEffect(() => {
    setLogoutModal(props.open);
  }, [props.open]);

  const handleLogout = (): void => {
    logout();
    $NavigationActions.reset(
      [{
        'name': $routeNames.login
      }], 0
    );
  }

  const handleCancel = (): void => {
    props.handleCancle();
    setLogoutModal(false);
  }

  return (
    <ThemeContext.Consumer>
      {(theme: Theme) => {
        return (
          <Modal
            animationType="slide"
            transparent={true}
            visible={logoutModal}
            onRequestClose={() => setLogoutModal(false)}
          >
            <View
              style={{
                flex: 1,
                justifyContent: 'center',
                alignItems: 'center',
                backgroundColor: 'rgba(0, 0, 0, 0.5)',
              }}
            >
              <View style={styles.subContainer} >
                <View style={styles.rusureContainer} >
                  <AppText
                    style={{
                      textAlign: 'center',
                      fontWeight: 700,
                      fontSize: 16,
                      // lineHeight: 16
                    }}
                  >
                    {$i18n.t('logout_message')}
                  </AppText>
                </View>
                <View
                  style={{
                    flexDirection: 'row',
                    justifyContent: 'space-between'
                  }}
                >
                  <TouchableOpacity
                    style={styles.cancelBtnContainer}
                    onPress={() => handleCancel()}>
                    <AppText style={{fontWeight: 700}}>
                      {$i18n.t('cancel')}
                    </AppText>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.activateTextContainer}
                    onPress={() => handleLogout()}
                  >
                    <AppText style={styles.confirmBtnText}>
                      {$i18n.t('confirm')}
                    </AppText>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </Modal>
        );
      }}
    </ThemeContext.Consumer>
  )
}

export default LogoutModal;

import React from 'react';
import {StyleSheet, TouchableOpacity} from 'react-native';
import TestRenderer, {act} from 'react-test-renderer';
import LogoutModal from '../src/components/logout-modal/logout-modal';
import {APP_THEME_COLOR} from '../src/style/theme/theme-common';
import styles from '../src/components/logout-modal/logout-modal.styles';

const mockLogout = jest.fn();
const mockReset = jest.fn();
const mockHandleCancel = jest.fn();

jest.mock('react-native-extended-stylesheet', () => ({
  __esModule: true,
  default: {
    create: <T,>(styleSheet: T): T => styleSheet,
  },
}));

jest.mock('../src/hooks/auth-hook-context.tsx', () => ({
  useAuth: () => ({
    logout: mockLogout,
  }),
}));

jest.mock('../src/components/app-text/app-text', () => {
  const ReactModule = require('react');
  const ReactNative = require('react-native');

  return ({children, ...props}: {children: React.ReactNode}) =>
    ReactModule.createElement(ReactNative.Text, props, children);
});

jest.mock('../src/style/theme/theme-context.tsx', () => ({
  ThemeContext: {
    Consumer: ({children}: {children: (theme: object) => React.ReactNode}) =>
      children({}),
  },
}));

const globalWithLogoutDependencies = global as typeof globalThis & {
  $NavigationActions: {reset: jest.Mock};
  $i18n: {t: (key: string) => string};
  $routeNames: {login: string};
};

globalWithLogoutDependencies.$NavigationActions = {reset: mockReset};
globalWithLogoutDependencies.$i18n = {
  t: (key: string): string => key,
};
globalWithLogoutDependencies.$routeNames = {
  login: 'LoginScreen',
};

describe('LogoutModal', () => {
  beforeEach(() => {
    mockLogout.mockClear();
    mockReset.mockClear();
    mockHandleCancel.mockClear();
  });

  test('uses APP_THEME_COLOR for the confirm button background', () => {
    expect(styles.activateTextContainer.backgroundColor).toBe(APP_THEME_COLOR);
  });

  test('confirming logout uses the shared auth logout and login reset', () => {
    let renderer: TestRenderer.ReactTestRenderer;

    act(() => {
      renderer = TestRenderer.create(
        <LogoutModal open={true} handleCancle={mockHandleCancel} />,
      );
    });

    const confirmButton = renderer!.root.findAllByType(TouchableOpacity).find(
      (node) => StyleSheet.flatten(node.props.style)?.backgroundColor === APP_THEME_COLOR,
    );

    expect(confirmButton).toBeDefined();

    act(() => {
      confirmButton?.props.onPress();
    });

    expect(mockLogout).toHaveBeenCalledTimes(1);
    expect(mockReset).toHaveBeenCalledWith(
      [{name: 'LoginScreen'}],
      0,
    );
  });
});

import React from 'react';
import TestRenderer, {act} from 'react-test-renderer';
import CustomDrawerContent from '../src/components/custom-drawer/custom-drawer-content';
import DrawerItem from '../src/components/drawer-row-item/drawer-row-item';

const mockCloseDrawer = jest.fn();
const mockDispatch = jest.fn();
let mockLogoutModalOpen = false;

jest.mock('react-native-extended-stylesheet', () => ({
  __esModule: true,
  default: {
    create: <T,>(styleSheet: T): T => styleSheet,
  },
}));

jest.mock('@react-navigation/native', () => ({
  CommonActions: {
    navigate: (payload: object) => payload,
  },
  useNavigation: () => ({
    dispatch: mockDispatch,
  }),
}));

jest.mock('../src/store/AppContext', () => ({
  useAppState: () => ({
    user: {name: 'New Town Levinal'},
  }),
}));

jest.mock('../src/hooks/useCurrentRoute', () => ({
  useCurrentRoute: () => 'ProfileScreen',
}));

jest.mock('react-native-safe-area-context', () => ({
  useSafeAreaInsets: () => ({
    bottom: 0,
    left: 0,
    right: 0,
    top: 0,
  }),
}));

jest.mock('../src/components/name-avatar-component/name-avatar-component', () =>
  'MockAvatar',
);

jest.mock('../src/assets/svg/index', () => {
  const ReactModule = require('react');
  const {View} = require('react-native');
  const MockIcon = (): React.ReactElement =>
    ReactModule.createElement(View);

  return new Proxy(
    {},
    {
      get: () => MockIcon,
    },
  );
});

jest.mock('../src/components/logout-modal/logout-modal', () => {
  const ReactModule = require('react');
  const {View} = require('react-native');

  return ({open}: {open: boolean}) => {
    mockLogoutModalOpen = open;
    return ReactModule.createElement(View, {testID: 'logout-modal', open});
  };
});

jest.mock('../src/style/theme/theme-context.tsx', () => ({
  ThemeContext: {
    Consumer: ({children}: {children: (theme: object) => React.ReactNode}) =>
      children({}),
  },
}));

const globalWithDrawerDependencies = global as typeof globalThis & {
  $i18n: {t: (key: string) => string};
  $routeNames: Record<string, string>;
};

globalWithDrawerDependencies.$i18n = {
  t: (key: string): string => key,
};
globalWithDrawerDependencies.$routeNames = {
  appointments: 'AppointmentsScreen',
  concierge: 'ConciergeScreen',
  profile: 'ProfileScreen',
  transactionHistory: 'TransactionHistoryScreen',
};

describe('CustomDrawerContent logout', () => {
  beforeEach(() => {
    mockCloseDrawer.mockClear();
    mockDispatch.mockClear();
    mockLogoutModalOpen = false;
  });

  test('opens the same logout confirmation modal used by settings', () => {
    let renderer: TestRenderer.ReactTestRenderer;

    act(() => {
      renderer = TestRenderer.create(
        <CustomDrawerContent closeDrawer={mockCloseDrawer} />,
      );
    });

    expect(mockLogoutModalOpen).toBe(false);

    const signOutItem = renderer!.root
      .findAllByType(DrawerItem)
      .find((node) => node.props.text === 'sign_out');

    expect(signOutItem).toBeDefined();

    act(() => {
      signOutItem?.props.onPress();
    });

    expect(mockLogoutModalOpen).toBe(true);
    expect(mockCloseDrawer).not.toHaveBeenCalled();
    expect(mockDispatch).not.toHaveBeenCalled();
  });
});
